use std::fs

fn is_leap(y: int) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn dim(y: int, m: int) -> int {
    if m == 2 {
        if is_leap(y) { 29 } else { 28 }
    } else if m == 4 || m == 6 || m == 9 || m == 11 {
        30
    } else {
        31
    }
}

fn all_digits(s: string) -> bool {
    if s.len() == 0 { return false }
    for c in s.chars() {
        if c < '0' || c > '9' { return false }
    }
    true
}

// returns days since 1970-01-01, or -1000000 if invalid
fn parse_date(s: string) -> int {
    let bad = -1000000
    let parts: Vec<string> = s.split("-").collect()
    if parts.len() != 3 { return bad }
    if parts[0].len() != 4 || parts[1].len() != 2 || parts[2].len() != 2 { return bad }
    if !all_digits(parts[0]) || !all_digits(parts[1]) || !all_digits(parts[2]) { return bad }
    let y: int = parts[0].parse::<int>().unwrap_or(0)
    let m: int = parts[1].parse::<int>().unwrap_or(0)
    let d: int = parts[2].parse::<int>().unwrap_or(0)
    if y < 1900 || y > 2100 { return bad }
    if m < 1 || m > 12 { return bad }
    if d < 1 || d > dim(y, m) { return bad }
    let yy = if m <= 2 { y - 1 } else { y }
    let era = yy / 400
    let yoe = yy - era * 400
    let mp = (m + 9) % 12
    let doy = (153 * mp + 2) / 5 + d - 1
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy
    era * 146097 + doe - 719468
}

fn main() {
    let names = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"]
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let t = line.trim()
        if t.len() == 0 { continue }
        let toks: Vec<string> = t.split_whitespace().collect()
        if toks.len() != 2 {
            println("invalid")
            continue
        }
        let a = parse_date(toks[0])
        let b = parse_date(toks[1])
        if a == -1000000 || b == -1000000 {
            println("invalid")
            continue
        }
        let lo = if a < b { a } else { b }
        let diff = if a < b { b - a } else { a - b }
        let wd = ((lo + 4) % 7 + 7) % 7
        println("${diff} ${names[wd as usize]}")
    }
}

